from gurobipy import GRB

model = gp.Model(env=env)

# Define parameters
supply = [[20, 30], [40, 10]]
demand = [[30, 30], [30, 10]]
limit = [[35, 25], [25, 30]]
cost = [[[2, 3], [4, 1]], [[3, 2], [2, 4]]]

# Add variables
X = {}
for i in range(2):
    for j in range(2):
        for p in range(2):
            var_name = f'X_{i}_{j}_{p}'
            X[(i,j,p)] = model.addVar(lb=0, vtype=GRB.INTEGER, name=var_name)

# Set objective
obj = 0
for i in range(2):
    for j in range(2):
        for p in range(2):
            obj += cost[i][j][p] * X[(i,j,p)]
model.setObjective(obj, GRB.MINIMIZE)

# Add supply constraints
for i in range(2):
    for p in range(2):
        sum_expr = 0
        for j in range(2):
            sum_expr += X[(i,j,p)]
        model.addConstr(sum_expr == supply[i][p], f"Supply_{i}_{p}")

# Add demand constraints
for j in range(2):
    for p in range(2):
        sum_expr = 0
        for i in range(2):
            sum_expr += X[(i,j,p)]
        model.addConstr(sum_expr == demand[j][p], f"Demand_{j}_{p}")

# Add ship limit constraints
for i in range(2):
    for j in range(2):
        sum_expr = 0
        for p in range(2):
            sum_expr += X[(i,j,p)]
        model.addConstr(sum_expr <= limit[i][j], f"Limit_{i}_{j}")

model.optimize()

if model.Status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.ObjVal:.17g}")
